 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    non_bg_counts = Counter(v for row in grid for v in row if v != background)
    target = non_bg_counts.most_common(1)[0][0]

    # Find the connected non-background, non-target component that serves as
    # the colored stamp; its bounding-box center is aligned to each target.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (background, target) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc, grid[rr][cc]))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] not in (background, target)):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)
    stamp = max(components, key=len)
    anchor_r = (min(r for r, c, v in stamp) + max(r for r, c, v in stamp)) // 2
    anchor_c = (min(c for r, c, v in stamp) + max(c for r, c, v in stamp)) // 2

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target:
                for sr, sc, color in stamp:
                    rr, cc = r + sr - anchor_r, c + sc - anchor_c
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
